<?php
namespace App\Services\Inventory;
use App\Models\Inventory\{InventoryRequest,InventoryApprovalStep}; use Illuminate\Support\Facades\DB;
class InventoryApprovalService { public function createApprovalChain(InventoryRequest $r):void{$roles=['warehouse_manager'];if((float)$r->estimated_value>=(float)config('inventory.large_issue_threshold',1000))$roles=['warehouse_manager','finance_manager','general_manager'];$r->approvals()->delete();foreach($roles as $i=>$role)InventoryApprovalStep::create(['inventory_request_id'=>$r->id,'step_order'=>$i+1,'approver_role'=>$role,'status'=>$i===0?'pending':'waiting']);$r->update(['status'=>'pending_approval']);} public function approve(InventoryApprovalStep $step,string $decision,?string $comment):void{DB::transaction(function()use($step,$decision,$comment){$step=InventoryApprovalStep::lockForUpdate()->findOrFail($step->id);abort_unless($step->status==='pending',422);$step->update(['status'=>$decision==='approved'?'approved':'rejected','comment'=>$comment,'approver_account_id'=>session('administrative_account_id')??auth()->id(),'acted_at'=>now()]);$r=$step->request()->lockForUpdate()->first();if($decision!=='approved'){$r->update(['status'=>'rejected']);return;}$next=$r->approvals()->where('step_order','>',$step->step_order)->where('status','waiting')->orderBy('step_order')->first();if($next){$next->update(['status'=>'pending']);}else{$r->update(['status'=>'approved_for_issue']);}});}}
